#!/usr/bin/env python3"""PEAD Path B Scoring Analysis==============================Re-runs the PEAD backtest, stores ALL trade-level data to pead_results.db,then analyzes whether EPS surprise magnitude predicts return magnitude.Output: scoring recommendation table -> Score 2/3/4 per surprise bucket        feeds directly into pead_scanner.py signal scoring.Usage:    python3 pead_scoring.py            # Full run    python3 pead_scoring.py --sample 500  # Fast test    python3 pead_scoring.py --from-db     # Re-analyze from existing DB (no re-run)"""import sysimport argparseimport sqlite3import osimport contextlibimport warningsfrom pathlib import Pathfrom datetime import datetime, timedeltaimport pandas as pdimport numpy as npimport yfinance as yffrom scipy import statswarnings.filterwarnings('ignore')sys.path.insert(0, str(Path(__file__).parent))import config as cfgSCRIPT_DIR   = Path(__file__).parentDB_PATH      = SCRIPT_DIR / cfg.EARNINGS_DBRESULTS_DB   = SCRIPT_DIR / 'pead_results.db'PRIMARY_HOLD = 4   # weeks - the deployed hold period# ---------------------------------------------------------------------------# Surprise magnitude buckets (applied to abs(surprise_pct))# ---------------------------------------------------------------------------BULL_BUCKETS = [    ('5-10%',   5,   10),    ('10-20%',  10,  20),    ('20-30%',  20,  30),    ('30-50%',  30,  50),    ('50%+',    50,  999),]BEAR_BUCKETS = [    ('5-10%',   5,   10),    ('10-20%',  10,  20),    ('20-30%',  20,  30),    ('30%+',    30,  999),]# ---------------------------------------------------------------------------# DB helpers# ---------------------------------------------------------------------------def init_results_db(conn):    conn.execute("""        CREATE TABLE IF NOT EXISTS pead_trades (            id              INTEGER PRIMARY KEY AUTOINCREMENT,            run_date        TEXT,            ticker          TEXT,            report_date     TEXT,            entry_date      TEXT,            signal          TEXT,            surprise_pct    REAL,            eps_actual      REAL,            eps_estimated   REAL,            sector          TEXT,            market_cap      REAL,            entry_price     REAL,            ret_2w          REAL,            ret_4w          REAL,            ret_8w          REAL,            surprise_bucket TEXT        )    """)    conn.commit()def save_trades(conn, trades_df, run_date):    rows = []    for _, r in trades_df.iterrows():        rows.append((            run_date,            r.get('ticker'),            str(r.get('report_date', ''))[:10],            str(r.get('entry_date', ''))[:10],            r.get('signal'),            r.get('surprise_pct'),            r.get('eps_actual'),            r.get('eps_estimated'),            r.get('sector', ''),            r.get('market_cap'),            r.get('entry_price'),            r.get('ret_2w'),            r.get('ret_4w'),            r.get('ret_8w'),            r.get('surprise_bucket', ''),        ))    conn.executemany("""        INSERT INTO pead_trades            (run_date, ticker, report_date, entry_date, signal, surprise_pct,             eps_actual, eps_estimated, sector, market_cap, entry_price,             ret_2w, ret_4w, ret_8w, surprise_bucket)        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)    """, rows)    conn.commit()    print(f"  Saved {len(rows):,} trades to {RESULTS_DB}")# ---------------------------------------------------------------------------# Signal loading (from pead_data.db)# ---------------------------------------------------------------------------def load_signals(beat_threshold, miss_threshold):    conn = sqlite3.connect(str(DB_PATH))    conditions = [        f'(surprise_pct >= {beat_threshold} OR surprise_pct <= -{miss_threshold})',        'eps_actual IS NOT NULL',        'eps_estimated IS NOT NULL',        f'ABS(eps_estimated) >= {cfg.MIN_ABS_EPS}',    ]    if cfg.BACKTEST_START:        conditions.append(f'e.report_date >= "{cfg.BACKTEST_START}"')    if cfg.BACKTEST_END:        conditions.append(f'e.report_date <= "{cfg.BACKTEST_END}"')    query = f"""        SELECT e.ticker, e.report_date, e.eps_actual, e.eps_estimated,               e.surprise_pct, m.sector, m.market_cap        FROM earnings e        LEFT JOIN ticker_metadata m ON e.ticker = m.ticker        WHERE {' AND '.join(conditions)}        ORDER BY e.report_date, e.ticker    """    df = pd.read_sql_query(query, conn)    conn.close()    df['report_date'] = pd.to_datetime(df['report_date'])    df['signal'] = np.where(df['surprise_pct'] >= beat_threshold, 'BULL', 'BEAR')    return df# ---------------------------------------------------------------------------# Price fetching + forward returns# ---------------------------------------------------------------------------def fetch_prices(ticker, price_start, price_end):    try:        data = yf.download(ticker, start=price_start, end=price_end,                           progress=False, auto_adjust=True)        if data is None or data.empty:            return None        s = data['Close'].squeeze().dropna()        s.index = pd.to_datetime(s.index)        return s if not s.empty else None    except Exception:        return Nonedef compute_forward_returns(signals_df):    tickers      = signals_df['ticker'].unique().tolist()    price_start  = (pd.to_datetime(cfg.BACKTEST_START) - timedelta(weeks=4)).strftime('%Y-%m-%d')    price_end    = cfg.BACKTEST_END or datetime.today().strftime('%Y-%m-%d')    hold_periods = cfg.HOLD_PERIODS    print(f"  Fetching prices for {len(tickers):,} tickers...")    price_cache = {}    for i, ticker in enumerate(tickers, 1):        if i % 100 == 0 or i == len(tickers):            print(f"    {i}/{len(tickers)} ({len(price_cache)} retrieved)", flush=True)        with open(os.devnull, 'w') as devnull:            with contextlib.redirect_stderr(devnull):                p = fetch_prices(ticker, price_start, price_end)        if p is not None:            price_cache[ticker] = p    print(f"  Got prices for {len(price_cache):,} of {len(tickers):,} tickers")    trades = []    for _, row in signals_df.iterrows():        ticker      = row['ticker']        report_date = row['report_date']        signal      = row['signal']        if ticker not in price_cache:            continue        prices = price_cache[ticker]        entry_from = report_date + timedelta(days=cfg.ENTRY_DELAY_DAYS)        future = prices[prices.index >= entry_from]        if future.empty:            continue        entry_date  = future.index[0]        entry_price = future.iloc[0]        trade = {            'ticker':        ticker,            'report_date':   report_date,            'entry_date':    entry_date,            'signal':        signal,            'surprise_pct':  row['surprise_pct'],            'eps_actual':    row['eps_actual'],            'eps_estimated': row['eps_estimated'],            'sector':        row.get('sector', ''),            'market_cap':    row.get('market_cap'),            'entry_price':   entry_price,        }        for weeks in hold_periods:            target  = entry_date + timedelta(weeks=weeks)            future_exit = prices[prices.index >= target]            if future_exit.empty:                trade[f'ret_{weeks}w'] = np.nan                continue            raw_ret = (future_exit.iloc[0] - entry_price) / entry_price            trade[f'ret_{weeks}w'] = raw_ret if signal == 'BULL' else -raw_ret        trades.append(trade)    return pd.DataFrame(trades)# ---------------------------------------------------------------------------# Bucket labeling# ---------------------------------------------------------------------------def assign_bucket(row):    abs_surp = abs(row['surprise_pct'])    buckets  = BULL_BUCKETS if row['signal'] == 'BULL' else BEAR_BUCKETS    for label, lo, hi in buckets:        if lo <= abs_surp < hi:            return label    return 'other'# ---------------------------------------------------------------------------# Statistics helpers# ---------------------------------------------------------------------------def compute_stats(rets):    rets = rets.dropna()    n = len(rets)    if n < 10:        return dict(n=n, alpha=np.nan, win_rate=np.nan, t_stat=np.nan, p_value=np.nan)    t, p = stats.ttest_1samp(rets, 0)    return dict(n=n, alpha=rets.mean(), win_rate=(rets > 0).mean(), t_stat=t, p_value=p)def sig_stars(p):    if pd.isna(p): return ''    if p < 0.01:   return '***'    if p < 0.05:   return '**'    if p < 0.10:   return '*'    return ''def score_recommendation(alpha, t_stat, p_value):    """    Translate bucket stats into a Score 2/3/4 recommendation.    Score 4 (8%)  = strong signal: alpha > 3%, t > 5, p < 0.01    Score 3 (5%)  = valid signal:  alpha > 1.5%, t > 2, p < 0.05    Score 2 (3%)  = marginal:      alpha > 0%, t > 1, p < 0.10    Score 1 (0%)  = skip / no signal    """    if pd.isna(alpha) or pd.isna(t_stat):        return 1, 'SKIP'    if alpha > 0.03 and t_stat > 5 and p_value < 0.01:        return 4, 'Score 4 ? 8%'    if alpha > 0.015 and t_stat > 2 and p_value < 0.05:        return 3, 'Score 3 ? 5%'    if alpha > 0 and t_stat > 1 and p_value < 0.10:        return 2, 'Score 2 ? 3%'    return 1, 'SKIP'# ---------------------------------------------------------------------------# Reporting# ---------------------------------------------------------------------------SEP = '=' * 80SEP2 = '-' * 80def print_bucket_analysis(trades, signal_type, buckets, hold_col='ret_4w'):    subset = trades[trades['signal'] == signal_type].copy()    print(f"\n  {signal_type} SIGNALS - Surprise Magnitude Scoring ({hold_col.replace('ret_','').replace('w',' week')} hold)")    print(f"  {'Bucket':<12} {'N':>6} {'Avg Return':>12} {'Win%':>8} {'t-stat':>8} {'p-val':>8}  {'Sig':<5}  Recommendation")    print("  " + "-" * 75)    recommendations = []    for label, lo, hi in buckets:        in_bucket = subset[            (subset['surprise_pct'].abs() >= lo) &            (subset['surprise_pct'].abs() <  hi)        ]        s = compute_stats(in_bucket[hold_col]) if not in_bucket.empty else compute_stats(pd.Series([], dtype=float))        score, rec = score_recommendation(s['alpha'], s['t_stat'], s['p_value'])        stars = sig_stars(s['p_value'])        if pd.isna(s['alpha']):            alpha_str = f"{'--':>12}"            win_str   = f"{'--':>8}"            t_str     = f"{'--':>8}"            p_str     = f"{'--':>8}"        else:            alpha_str = f"{s['alpha']:>+12.2%}"            win_str   = f"{s['win_rate']:>8.1%}"            t_str     = f"{s['t_stat']:>8.2f}"            p_str     = f"{s['p_value']:>8.4f}"        print(f"  {label:<12} {int(s['n']):>6} {alpha_str} {win_str} {t_str} {p_str}  {stars:<5}  {rec}")        recommendations.append((label, score, rec, s))    return recommendationsdef print_overall(trades, hold_col='ret_4w'):    col = trades[hold_col].dropna()    s   = compute_stats(col)    print(f"\n  OVERALL ({len(trades):,} trades, {hold_col})")    if not pd.isna(s['alpha']):        print(f"  Avg return: {s['alpha']:+.2%}  Win rate: {s['win_rate']:.1%}  t={s['t_stat']:.2f}  p={s['p_value']:.4f}  {sig_stars(s['p_value'])}")    bull = trades[trades['signal'] == 'BULL']    bear = trades[trades['signal'] == 'BEAR']    sb   = compute_stats(bull[hold_col].dropna())    ss   = compute_stats(bear[hold_col].dropna())    if not pd.isna(sb['alpha']):        print(f"  BULL: {sb['alpha']:+.2%}  Win: {sb['win_rate']:.1%}  t={sb['t_stat']:.2f}  ({int(sb['n'])} trades)")    if not pd.isna(ss['alpha']):        print(f"  BEAR: {ss['alpha']:+.2%}  Win: {ss['win_rate']:.1%}  t={ss['t_stat']:.2f}  ({int(ss['n'])} trades)")# ---------------------------------------------------------------------------# Q4 exclusion analysis# ---------------------------------------------------------------------------def print_q4_analysis(trades, hold_col='ret_4w'):    """Confirm Q4 exclusion rule - signal known to reverse in Jan/Feb reports."""    df = trades.copy()    df['report_month'] = pd.to_datetime(df['report_date']).dt.month    df['is_q4'] = df['report_month'].isin([1, 2])    q4     = df[df['is_q4']]    non_q4 = df[~df['is_q4']]    sq4    = compute_stats(q4[hold_col].dropna())    snq4   = compute_stats(non_q4[hold_col].dropna())    print(f"\n  Q4 EXCLUSION VALIDATION ({hold_col})")    print(f"  {'Period':<20} {'N':>6} {'Avg Return':>12} {'Win%':>8} {'t-stat':>8}  Sig")    print("  " + "-" * 60)    for label, s in [('Jan/Feb reports (Q4)', sq4), ('All other months', snq4)]:        if pd.isna(s['alpha']):            print(f"  {label:<20} {int(s['n']):>6} {'--':>12}")        else:            print(f"  {label:<20} {int(s['n']):>6} {s['alpha']:>+12.2%} {s['win_rate']:>8.1%} {s['t_stat']:>8.2f}  {sig_stars(s['p_value'])}")# ---------------------------------------------------------------------------# Main# ---------------------------------------------------------------------------def parse_args():    p = argparse.ArgumentParser(description='PEAD Path B Scoring Analysis')    p.add_argument('--sample',  type=int, default=None,   help='Random sample N signals (fast test)')    p.add_argument('--from-db', action='store_true',      help='Re-analyze from existing DB, skip backtest re-run')    p.add_argument('--beat',    type=float, default=cfg.BEAT_THRESHOLD)    p.add_argument('--miss',    type=float, default=cfg.MISS_THRESHOLD)    return p.parse_args()def load_from_db():    """Load the most recent run from pead_results.db."""    conn = sqlite3.connect(str(RESULTS_DB))    # Get most recent run_date    run_date = conn.execute("SELECT MAX(run_date) FROM pead_trades").fetchone()[0]    df = pd.read_sql_query(        "SELECT * FROM pead_trades WHERE run_date = ?", conn, params=(run_date,)    )    conn.close()    print(f"  Loaded {len(df):,} trades from DB (run: {run_date})")    return dfdef main():    args = parse_args()    run_date = datetime.today().strftime('%Y-%m-%d %H:%M:%S')    print()    print(SEP)    print("  PEAD PATH B - Surprise Magnitude Scoring Analysis")    print(f"  Run date:  {run_date}")    print(f"  Purpose:   Does EPS surprise magnitude predict return magnitude?")    print(f"             Answer feeds Score 2/3/4 into pead_scanner.py")    print(SEP)    # ---- Step 1: Get trade data ----    if args.from_db:        print("\n  Loading from existing DB...")        trades = load_from_db()    else:        if not DB_PATH.exists():            print(f"ERROR: {DB_PATH} not found. Run collect_earnings.py first.")            sys.exit(1)        print(f"\n  Loading signals (beat>={args.beat}%, miss>={args.miss}%)...")        signals = load_signals(args.beat, args.miss)        print(f"  {len(signals):,} signals  |  BULL: {(signals['signal']=='BULL').sum():,}  BEAR: {(signals['signal']=='BEAR').sum():,}")        print(f"  Date range: {signals['report_date'].min().date()} to {signals['report_date'].max().date()}")        print(f"  Unique tickers: {signals['ticker'].nunique():,}")        if args.sample and args.sample < len(signals):            print(f"  Sampling {args.sample} signals (fast test)...")            signals = signals.sample(n=args.sample, random_state=42).reset_index(drop=True)        print("\n  Running backtest (fetching forward returns)...")        trades = compute_forward_returns(signals)        print(f"  Trades with price data: {len(trades):,}")        if trades.empty:            print("  No trades computed. Check DB and price fetching.")            sys.exit(1)        # Assign surprise buckets        trades['surprise_bucket'] = trades.apply(assign_bucket, axis=1)        # Save to results DB        print(f"\n  Saving to {RESULTS_DB}...")        conn = sqlite3.connect(str(RESULTS_DB))        init_results_db(conn)        # Clear previous runs before saving (keep DB fresh)        conn.execute("DELETE FROM pead_trades")        conn.commit()        save_trades(conn, trades, run_date)        conn.close()    # ---- Step 2: Analysis ----    hold_col = f'ret_{PRIMARY_HOLD}w'    if hold_col not in trades.columns:        print(f"ERROR: column {hold_col} not found. Check HOLD_PERIODS in config.")        sys.exit(1)    print()    print(SEP)    print("  RESULTS - FULL DATASET")    print(SEP)    print_overall(trades, hold_col)    print_q4_analysis(trades, hold_col)    print()    print(SEP)    print("  SCORING ANALYSIS BY SURPRISE MAGNITUDE")    print("  Scoring thresholds: Score 4 (alpha>3%, t>5)  Score 3 (alpha>1.5%, t>2)  Score 2 (alpha>0%, t>1)")    print(SEP)    bull_recs  = print_bucket_analysis(trades, 'BULL', BULL_BUCKETS, hold_col)    bear_recs  = print_bucket_analysis(trades, 'BEAR', BEAR_BUCKETS, hold_col)    # ---- Step 3: Scoring recommendation summary ----    print()    print(SEP)    print("  SCORING RECOMMENDATION SUMMARY")    print("  (Wire these into pead_scanner.py signal scoring)")    print(SEP)    print(f"\n  {'Signal':<8} {'Bucket':<12} {'Avg Return':>12}  {'Recommendation'}")    print("  " + "-" * 50)    for label, score, rec, s in bull_recs:        alpha_str = f"{s['alpha']:>+12.2%}" if not pd.isna(s['alpha']) else f"{'--':>12}"        print(f"  {'BULL':<8} {label:<12} {alpha_str}  {rec}")    print()    for label, score, rec, s in bear_recs:        alpha_str = f"{s['alpha']:>+12.2%}" if not pd.isna(s['alpha']) else f"{'--':>12}"        print(f"  {'BEAR':<8} {label:<12} {alpha_str}  {rec}")    print()    print(SEP)    print("  NEXT STEPS")    print(SEP)    print("  1. Review scoring table above")    print("  2. Update pead_scanner.py: assign_score() should return 2/3/4")    print("     based on surprise_pct magnitude per this table")    print("  3. Test on PA: re-run scanner dry-run, confirm score field in email")    print("  4. Commit pead_scanner.py update + push to GitHub")    print()if __name__ == '__main__':    main()